// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(
        uint256 pk,
        uint256 premium,
        uint256 duration,
        uint256 expirationOffset,
        uint256 nonce,
        address erc20
    ) public {
        pk = bound(pk, 1, 0xfffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff);
        address maker = vm.addr(pk);
        premium = bound(premium, 0, 1 ether);
        duration = bound(duration, 1, 9999 days);
        expirationOffset = bound(expirationOffset, 1, 3650 days);

        // Deploy a minimal ERC20 with the selector that SafeTransferLib targets so fillOrder's
        // transferFrom call succeeds on the reference. We only need the long-call branch to succeed
        // far enough to reach the expiration write; the ERC20 transfers are no-ops returning true.
        MockERC20 m = new MockERC20();
        m.mint(maker, type(uint256).max);
        m.mint(address(this), type(uint256).max);

        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        uint256[] memory floorIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: address(m),
            strike: 0,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + expirationOffset,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 digest = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(pk, digest);
        bytes memory sig = abi.encodePacked(r, s, v);

        bytes32 orderHash = c.hashOrder(order);

        bool ok;
        try c.fillOrder(order, sig, floorIds) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference accepts non-expired orders and writes positionExpirations[orderHash] = now + duration.
        // Mutant rejects them (block.timestamp > expiration is false), so ok=false and no write.
        bool wrote = c.positionExpirations(uint256(orderHash)) != 0;
        assertTrue(ok && wrote);
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    function mint(address to, uint256 amt) external { balanceOf[to] += amt; }
    function transferFrom(address, address, uint256) external returns (bool) { return true; }
    function transfer(address, uint256) external returns (bool) { return true; }
    function approve(address, uint256) external returns (bool) { return true; }
}
